-- Status history (every workflow type: the whole path); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.sc_workflow_status w
 where w.doc_type in ('QT', 'CMT', 'BPK', 'OC', 'TEC', 'FEC', 'EC', 'LI', 'SF', 'SE', 'PCB', 'DAR', 'QC', 'PTJ', 'QDR', 'EPV')
   and w.doc_id in (select qt_id from ngep_sit.sc_qt where qt_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

